INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'telling-time'), (SELECT id FROM languages WHERE code = 'en'), 'Telling the time: “vaajle” and “vaajta”', '“Kiti vaajle?” asks the time and the answer uses “vaajle” (it has struck): “daha vaajle” = it''s ten. For when something happens, use “vaajta”: “nau vaajta” = at nine.');
