INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'past-tense'), (SELECT id FROM languages WHERE code = 'en'), 'The past: “gelo / gele” and “kela”', 'Going and coming change with the speaker: a man says “mi gelo”, a woman “mi gele” (I went). A verb with an object follows the object instead, so everyone says “mi aaraam kela” (I rested) and “mi paavbhaaji khaalli” (I ate pav bhaji, “paavbhaaji” is feminine).');
