INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'future-tense'), (SELECT id FROM languages WHERE code = 'en'), 'The future: “-in”, “-u” and “-uya”', '“Mi karin” (I will do) and “mi yein” (I will come) are the same for everyone. “Aapan jaau” = we will go; “aapan jaauya” = let''s go. “Tu yeshil ka?” = will you come?');
