INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'polite-questions'), (SELECT id FROM languages WHERE code = 'en'), 'Softer requests: “…al ka?”', 'To ask kindly, use the “tumhi” future as a question: “madat karal ka?” (would you help?), “ghyal ka?” (would you take?), “bolval ka?” (would you call?). It is softer than the plain “-a” request (“dya”, “sanga”).');
