INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'mr') AND slug = 'liking'), (SELECT id FROM languages WHERE code = 'en'), 'Liking things: “mala … aavadta”', 'Marathi says “to me, X is liked”: “mala chaha aavadto” (I like tea), “mala misal aavadte” (I like misal). The ending follows the thing you like, not you, so it is the same for everyone.');
